ns3:test-case.ns3:test:
( fn:filter( (), if ( fn:current-dateTime() eq
                            fn:dateTime( fn:current-date(),
                                         fn:current-time() ))
                         then fn:exists#1
                         else 1 ),
              fn:filter( (), if ( fn:current-dateTime() eq
                            fn:dateTime( fn:current-date(),
                                         fn:current-time() ))
                         then 1
                         else fn:exists#1 ) )

fn:filter( (), if ( fn:current-dateTime() eq
                          fn:dateTime( fn:current-date(),
                                       fn:current-time() ))
                       then fn:exists#1
                       else 1 )

for $i in (1000, 2000)
let $x := year-from-date(current-date()) idiv $i
return fn:filter(10 to 20, function($it as xs:integer) as xs:boolean {$it - 10 gt $x} )
